namespace ghidra.app.plugin.core.equate;

using ghidra.docking.settings;
using ghidra.program.model.listing;
using ghidra.program.model.scalar;

public class ConvertToSignedHexAction : AbstractConvertAction {
	public static string ACTION_NAME = "Convert To Signed Hex";

	public ConvertToSignedHexAction(EquatePlugin plugin) : base(plugin, ACTION_NAME, true)
    {
	}

	/* @Override */
	protected string getMenuName(Program program, Scalar scalar, bool isData) {
		return isData
				? null
				: getStandardLengthString("Signed Hex:") + convertToString(program, scalar, false);
	}

	/* @Override */
	protected string convertToString(Program program, Scalar scalar, bool isData) {
		if (isData) {
			return null; // unsupported
		}
		long v = scalar.getSignedValue();
		string valueStr = Long.toString(v, 16).toUpperCase();
		if (v < 0) {
			// use of substring removes '-' prefix for negative value
			return "-0x" + valueStr.substring(1);
		}
		return "0x" + valueStr;
	}

	/* @Override */
	protected int getFormatChoice() {
		return FormatSettingsDefinition.HEX;
	}

}
